<script setup lang="ts">
import type { Role } from '~/types/lapormas'
definePageMeta({ layout: 'app', middleware: 'auth', title: 'Manajemen Akun' })
const { state, addUser, resetPassword, toggleUserActive } = useLaporMas()
const showForm = ref(false)
const errorMessage = ref('')
const success = ref('')
const form = reactive({ name: '', username: '', password: 'lapormas123', role: 'masyarakat' as Role, address: '', phone: '' })
const roleNames: Record<Role, string> = { masyarakat: 'Masyarakat', petugas: 'Petugas Keamanan', admin: 'Admin', rt: 'Ketua RT' }
const users = computed(() => [...state.value.users].sort((a,b) => a.name.localeCompare(b.name)))
function submit() { errorMessage.value = ''; success.value = ''; if (!form.name.trim() || !form.username.trim() || !form.password.trim() || !form.address.trim()) { errorMessage.value = 'Lengkapi seluruh data wajib.'; return } const result = addUser({ ...form }); if (!result.ok) { errorMessage.value = result.message; return } success.value = result.message; showForm.value = false; Object.assign(form, { name: '', username: '', password: 'lapormas123', role: 'masyarakat', address: '', phone: '' }) }
function reset(userId: string, username: string) { const next = window.prompt(`Masukkan password demo baru untuk ${username}:`, 'lapormas123'); if (next && resetPassword(userId, next)) success.value = `Password akun ${username} berhasil direset.` }
function toggle(userId: string, username: string, active: boolean) { if (window.confirm(`${active ? 'Nonaktifkan' : 'Aktifkan'} akun ${username}?`)) toggleUserActive(userId) }
</script>
<template><div class="page-stack"><div class="page-title-row"><div><div class="eyebrow">PENGELOLAAN PENGGUNA · F001</div><h1>Manajemen akun</h1><p>Admin membuat akun, mereset password, dan mengatur status akses pengguna.</p></div><button class="btn btn-primary" @click="showForm = !showForm">＋ Buat akun baru</button></div><div v-if="success" class="success-banner"><span>✓</span>{{ success }}<button @click="success = ''">×</button></div><section v-if="showForm" class="panel create-user-panel"><div class="panel-heading"><div><h3>Formulir akun baru</h3><p>Informasi login akan dibagikan admin kepada pengguna.</p></div><button class="icon-button" @click="showForm = false">×</button></div><form class="user-form-grid" @submit.prevent="submit"><label class="field-label">Nama lengkap <em>*</em><input v-model="form.name" class="text-input" required/></label><label class="field-label">Username <em>*</em><input v-model="form.username" class="text-input" required/></label><label class="field-label">Password awal <em>*</em><input v-model="form.password" class="text-input" required/></label><label class="field-label">Peran <em>*</em><select v-model="form.role" class="text-input"><option value="masyarakat">Masyarakat</option><option value="petugas">Petugas Keamanan</option><option value="rt">Ketua RT</option><option value="admin">Admin</option></select></label><label class="field-label">Alamat / lokasi <em>*</em><input v-model="form.address" class="text-input" required/></label><label class="field-label">Nomor telepon<input v-model="form.phone" class="text-input"/></label><div v-if="errorMessage" class="form-error span-all">{{ errorMessage }}</div><div class="form-actions span-all"><span class="field-hint">Akun demo tidak memakai autentikasi server.</span><button type="button" class="btn btn-ghost" @click="showForm = false">Batal</button><button class="btn btn-primary">Simpan akun</button></div></form></section><section class="panel"><div class="panel-heading"><div><h3>Daftar pengguna</h3><p>{{ users.length }} akun terdaftar di prototipe ini.</p></div><span class="count-pill">{{ users.filter(u => u.active).length }} aktif</span></div><div class="table-wrap"><table class="data-table"><thead><tr><th>PENGGUNA</th><th>USERNAME</th><th>PERAN</th><th>STATUS</th><th>AKSI</th></tr></thead><tbody><tr v-for="user in users" :key="user.id"><td><div class="user-cell"><span class="table-avatar">{{ user.name.slice(0,1) }}</span><span><b>{{ user.name }}</b><small>{{ user.address }}</small></span></div></td><td>@{{ user.username }}</td><td>{{ roleNames[user.role] }}</td><td><span class="account-status" :class="user.active ? 'active' : 'inactive'"><i></i>{{ user.active ? 'Aktif' : 'Nonaktif' }}</span></td><td><div class="table-actions"><button class="text-button" @click="reset(user.id, user.username)">Reset password</button><button class="text-button" :class="user.active ? 'danger-text' : 'success-text'" @click="toggle(user.id, user.username, user.active)">{{ user.active ? 'Nonaktifkan' : 'Aktifkan' }}</button></div></td></tr></tbody></table></div></section><div class="privacy-note"><span>◈</span><div><b>Catatan keamanan prototipe</b><p>Password demo disimpan sebagai data lokal untuk simulasi. Jangan gunakan data pribadi atau password asli pada versi ini.</p></div></div></div></template>
